from z3 import *

def solve():
    V = 19
    E = [[Bool(f"e_{i}_{j}") if i < j else Bool(f"e_{j}_{i}") if i > j else False for j in range(V)] for i in range(V)]

    s = Solver()

    # At least 28 edges
    s.add(Sum([If(E[i][j], 1, 0) for i in range(V) for j in range(i+1, V)]) >= 28)

    # 3-colorable
    C = [Int(f"c_{i}") for i in range(V)]
    for i in range(V):
        s.add(C[i] >= 0, C[i] <= 2)
    for i in range(V):
        for j in range(i+1, V):
            s.add(Implies(E[i][j], C[i] != C[j]))

    # Girth >= 7 (no cycles of length 3, 4, 5, 6)
    # Length 3
    for i in range(V):
        for j in range(i+1, V):
            for k in range(j+1, V):
                s.add(Not(And(E[i][j], E[j][k], E[k][i])))

    # Length 4
    for i in range(V):
        for j in range(i+1, V):
            for k in range(j+1, V):
                for l in range(k+1, V):
                    # cycles: i-j-k-l-i, i-j-l-k-i, i-k-j-l-i
                    s.add(Not(And(E[i][j], E[j][k], E[k][l], E[l][i])))
                    s.add(Not(And(E[i][j], E[j][l], E[l][k], E[k][i])))
                    s.add(Not(And(E[i][k], E[k][j], E[j][l], E[l][i])))

    # Length 5
    import itertools
    for c in itertools.combinations(range(V), 5):
        for p in itertools.permutations(c[1:]):
            path = [c[0]] + list(p)
            edges = [E[path[m]][path[(m+1)%5]] for m in range(5)]
            s.add(Not(And(edges)))

    # Length 6
    for c in itertools.combinations(range(V), 6):
        for p in itertools.permutations(c[1:]):
            path = [c[0]] + list(p)
            edges = [E[path[m]][path[(m+1)%6]] for m in range(6)]
            s.add(Not(And(edges)))

    print("Solving...")
    if s.check() == sat:
        m = s.model()
        edges = []
        for i in range(V):
            for j in range(i+1, V):
                if is_true(m[E[i][j]]):
                    edges.append((i, j))
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

solve()

